def _part_root_dir(safe_pn: str) -> Path:
    """Return the part asset root, accepting standard and doubled layouts."""
    base = library_path("parts", safe_pn)
    doubled = base / safe_pn
    if doubled.exists() and doubled.is_dir():
        return doubled
    return base


def _part_rev_dir(safe_pn: str, safe_rev: str) -> Path:
    return _part_root_dir(safe_pn) / f"rev{safe_rev}"


def _part_asset_candidates(safe_pn: str, *relative_parts: str) -> List[Path]:
    """Candidate part asset paths, doubled layout first then standard layout."""
    base = library_path("parts", safe_pn)
    roots = []
    doubled = base / safe_pn
    if doubled.exists() and doubled.is_dir():
        roots.append(doubled)
    roots.append(base)
    return [root.joinpath(*relative_parts) for root in roots]


def _resolve_part_asset(safe_pn: str, *relative_parts: str) -> Optional[Path]:
    for candidate in _part_asset_candidates(safe_pn, *relative_parts):
        if candidate.exists():
            return candidate
    return None


# -- Library Intake Wizard -- stub-profile awareness (Step 1) -----------
#
# Per docs/library-intake-wizard-plan.md sect. 5.7, a profile written by the
# wizard's intake flow is marked with `source: "library_intake_stub"`.
# Downstream consumers (get_profile_details, run_inspection, the
# /api/profiles picker via SpatialInspector.list_profiles) must detect
# this and gate inspection actions so the operator never sees an
# incomplete-profile part presented as inspection-ready.
#
# This file owns the canonical detection rule + path-resolution helpers
# so the gates in /api/profile-details (sect. 9.5) and /api/inspect (sect. 9.6)
# stay consistent. Both gates use the same predicate so the UI and
# backend never disagree about which parts are stubs.

INTAKE_STUB_SOURCE = "library_intake_stub"
INTAKE_STUB_INSPECT_MESSAGE = (
    "This part has been added to the library, but no inspection profile "
    "has been authored yet."
)


def _is_intake_stub_profile(profile_data: Any) -> bool:
    """Single source of truth for the intake-stub detection rule (sect. 5.7).

    Returns True iff the parsed profile JSON has top-level
    `source == "library_intake_stub"`. Defensive: non-dict input returns
    False so a malformed/unreadable file does NOT silently get treated
    as a stub.
    """
    return isinstance(profile_data, dict) and profile_data.get("source") == INTAKE_STUB_SOURCE


def _resolve_profile_path(safe_pn: str) -> Optional[Path]:
    """Resolve the root-level profile JSON path for a part. Same candidate
    order get_profile_details uses, factored out so the run_inspection
    fail-fast gate can do the same lookup without re-reading the file."""
    library_dir = library_path()
    candidates = [
        library_dir / f"{safe_pn}_inspection_profile.json",
        library_dir / f"{safe_pn}.json",
        *_part_asset_candidates(safe_pn, "revA", f"{safe_pn}_inspection_profile.json"),
        *_part_asset_candidates(safe_pn, "revA", f"{safe_pn}.json"),
    ]
    return next((p for p in candidates if p.exists()), None)


def _load_profile_if_present(part_number: str) -> Optional[dict]:
    """Read the raw profile JSON for a part, or None if missing or
    unreadable. Used by the stub-awareness gates -- never raises
    (callers fall through to existing handler behaviour on None)."""
    safe_pn = re.sub(r"[^\w\-]", "", part_number or "")
    if not safe_pn:
        return None
    path = _resolve_profile_path(safe_pn)
    if path is None:
        return None
    try:
        with open(path, "r", encoding="utf-8-sig") as f:
            return json.load(f)
    except Exception:
        return None


def _ensure_inspector() -> Optional[SpatialInspector]:
    """Return the process inspector, lazily creating it when startup was skipped.

    Some demo launches run uvicorn with lifespan disabled to avoid optional
    browser startup cost. In that mode the global inspector stays None, but the
    first app screen still needs profile data.
    """
    global inspector
    if inspector is not None:
        return inspector
    try:
        inspector = SpatialInspector(library_dir=str(LIBRARY_DIR))
        logger.info("SpatialInspector initialized lazily for profile access.")
        return inspector
    except Exception as e:
        logger.warning("SpatialInspector unavailable; using disk profile fallback: %s", e)
        return None


def _profile_feature_count(data: dict) -> int:
    features = data.get("features", [])
    if isinstance(features, list):
        return len(features)
    if isinstance(features, dict):
        items = features.get("items") or features.get("features") or []
        return len(items) if isinstance(items, list) else 0
    return 0


_PREPARED_ASSEMBLY_ASSETS = {
    "model": "visuals/assembly.glb",
    "front": "visuals/presentation/front.png",
    "top": "visuals/presentation/top.png",
    "right": "visuals/presentation/right.png",
    "isometric": "visuals/presentation/isometric.png",
}


def _assembly_profile_picker_entry(
    assembly_number: str,
    data: dict,
    *,
    has_views: bool,
    source: Optional[str] = None,
) -> dict:
    identity = data.get("identity", {}) or {}
    stats = data.get("statistics", {}) or {}
    description = (
        identity.get("description")
        or (identity.get("customProperties") or {}).get("Description")
        or assembly_number
    )
    unique_count = stats.get("uniquePartCount")
    if unique_count is None:
        unique_count = len(data.get("partDataCache", {}) or {})
    entry = {
        "part_number": assembly_number,
        "part_name": description,
        "feature_count": int(unique_count or 0),
        "has_views": bool(has_views),
        "context_kind": "assembly",
        "component_count": int(stats.get("totalComponents") or 0),
        "unique_part_count": int(unique_count or 0),
    }
    if source:
        entry["source"] = source
    knowledge = data.get("assemblyKnowledge")
    if isinstance(knowledge, dict):
        entry["assembly_knowledge"] = {
            "packageId": knowledge.get("packageId"),
            "packageRevision": knowledge.get("packageRevision"),
            "readiness": knowledge.get("readiness"),
            "productionEligible": knowledge.get("productionEligible"),
        }
    return entry


def _discover_prepared_assembly_sources() -> Dict[str, dict]:
    """Resolve validated Assembly Knowledge Packages for the Assembly tab."""
    training_root = PROCESS_MAP_TRAINING_ROOT
    if not training_root.is_dir():
        return {}
    repository = AssemblyKnowledgeRepository(training_root)
    readiness_rank = {
        "structure_ready": 1,
        "function_ready": 2,
        "planning_ready": 3,
        "production_ready": 4,
    }
    resolved: Dict[str, dict] = {}
    for product_root in sorted(training_root.iterdir(), key=lambda path: path.name):
        product_id = product_root.name
        if not product_root.is_dir() or not (product_root / "assembly_knowledge").is_dir():
            continue
        try:
            packages = repository.list_packages(product_id)
        except (
            FacilityGenerationRunRepositoryError,
            KeyError,
            TypeError,
            ValueError,
        ) as exc:
            logger.warning(
                "Skipping prepared assembly profile %s: %s",
                product_id,
                exc,
            )
            continue
        packages = sorted(
            packages,
            key=lambda item: (
                bool(item.get("productionEligible")),
                readiness_rank.get(str(item.get("readiness") or ""), 0),
                str(item.get("packageRevision") or ""),
                str(item.get("packageId") or ""),
            ),
            reverse=True,
        )
        for package in packages:
            package_id = str(package.get("packageId") or "")
            try:
                documents = repository.read(product_id, package_id)
                asset_hashes = documents["package.json"].get("assetHashes", {})
                if _PREPARED_ASSEMBLY_ASSETS["model"] not in asset_hashes:
                    continue
                assets: Dict[str, Path] = {}
                for key, relative_path in _PREPARED_ASSEMBLY_ASSETS.items():
                    if relative_path not in asset_hashes:
                        continue
                    assets[key] = repository.resolve_asset(
                        product_id,
                        package_id,
                        relative_path,
                    )
                if "model" not in assets:
                    continue
                resolved[product_id] = {
                    "productId": product_id,
                    "packageId": package_id,
                    "packageRevision": documents["package.json"].get(
                        "packageRevision"
                    ),
                    "profile": build_legacy_assembly_profile(documents),
                    "assets": assets,
                }
                break
            except Exception as exc:
                logger.warning(
                    "Skipping prepared assembly package %s/%s: %s",
                    product_id,
                    package_id,
                    exc,
                )
    return resolved


def _prepared_assembly_asset_path(
    assembly_number: str,
    asset_key: str,
) -> Optional[Path]:
    source = prepared_assembly_sources.get(assembly_number)
    if not isinstance(source, dict):
        return None
    path = (source.get("assets") or {}).get(asset_key)
    return path if isinstance(path, Path) and path.is_file() else None


def _resolve_assembly_model_path(
    assembly_number: str,
    revision: Optional[str] = None,
) -> Optional[Path]:
    assemblies_dir = library_path("assemblies")
    if revision:
        safe_rev = re.sub(r"[^\w]", "", revision)
        candidate = (
            assemblies_dir
            / assembly_number
            / f"rev{safe_rev}"
            / f"{assembly_number}_colored.glb"
        )
    else:
        candidate = assemblies_dir / f"{assembly_number}_colored.glb"
    if candidate.is_file():
        return candidate
    if revision:
        return None
    return _prepared_assembly_asset_path(assembly_number, "model")


def _list_part_profiles_from_disk() -> List[dict]:
    """List inspection profiles directly from the library without API keys."""
    profiles: List[dict] = []
    library_dir = library_path()
    seen_paths: set[Path] = set()
    for profile_path in sorted(library_dir.rglob("*_inspection_profile.json")):
        if profile_path in seen_paths:
            continue
        seen_paths.add(profile_path)
        part_number = profile_path.name.replace("_inspection_profile.json", "")
        try:
            with open(profile_path, "r", encoding="utf-8-sig") as f:
                data = json.load(f)
        except Exception as e:
            logger.warning("Skipping unreadable profile %s: %s", profile_path, e)
            continue
        if not isinstance(data, dict):
            continue

        pn = str(data.get("part_number") or part_number)
        view_roots = [library_dir, profile_path.parent]
        has_views = any((root / f"{pn}_view_front.png").exists() for root in view_roots)
        entry = {
            "part_number": pn,
            "part_name": data.get("part_name") or data.get("name") or "",
            "feature_count": _profile_feature_count(data),
            "has_views": has_views,
        }
        source = data.get("source")
        if source:
            entry["source"] = source
        profiles.append(entry)
    return profiles


def _list_assembly_profiles_from_disk() -> List[dict]:
    """Expose assemblies in the same picker payload as inspection profiles."""
    assemblies_dir = library_path("assemblies")
    if not assemblies_dir.exists():
        return []

    profiles: List[dict] = []
    for assembly_path in sorted(assemblies_dir.glob("*_assembly.json")):
        assy_number = assembly_path.stem.replace("_assembly", "")
        try:
            with open(assembly_path, "r", encoding="utf-8-sig") as f:
                data = json.load(f)
        except Exception as e:
            logger.warning("Skipping unreadable assembly profile %s: %s", assembly_path, e)
            continue
        if not isinstance(data, dict):
            continue

        profiles.append(
            _assembly_profile_picker_entry(
                assy_number,
                data,
                has_views=(
                    assemblies_dir / f"{assy_number}_view_front.png"
                ).exists(),
            )
        )
    return profiles


def _list_prepared_assembly_profiles() -> List[dict]:
    profiles = []
    for assembly_number, source in sorted(prepared_assembly_sources.items()):
        data = source.get("profile")
        if not isinstance(data, dict):
            continue
        profiles.append(
            _assembly_profile_picker_entry(
                assembly_number,
                data,
                has_views=bool(
                    _prepared_assembly_asset_path(assembly_number, "front")
                ),
                source=str(source.get("source") or "assembly_knowledge_package"),
            )
        )
    return profiles


def _merge_profile_entries(*profile_groups: List[dict]) -> List[dict]:
    merged: Dict[str, dict] = {}
    for profiles in profile_groups:
        for profile in profiles or []:
            part_number = str(profile.get("part_number") or "").strip()
            if not part_number:
                continue
            # Prefer the first real inspection profile if a duplicate appears.
            if part_number not in merged:
                merged[part_number] = profile
    return sorted(merged.values(), key=lambda p: str(p.get("part_number", "")))


def _find_highlight_boxes_path(part_number: str, library_dir: str | Path) -> Optional[Path]:
    """Locate ``{part}_highlight_boxes.json`` in the inspection library."""
    safe_part_number = sanitize_part_number(part_number)
    if not safe_part_number:
        return None

    library_path = Path(library_dir)
    filename = f"{safe_part_number}_highlight_boxes.json"

    direct = library_path / filename
    if direct.exists():
        return direct

    for candidate in (
        library_path / "drawings" / filename,
        library_path / "highlight_boxes" / filename,
    ):
        if candidate.exists():
            return candidate

    return None


def _find_dimension_descriptions_path(part_number: str, library_dir: str | Path) -> Optional[Path]:
    """Locate ``{part}_dimension_descriptions.json`` in the inspection library."""
    safe_part_number = sanitize_part_number(part_number)
    if not safe_part_number:
        return None

    library_path = Path(library_dir)
    filename = f"{safe_part_number}_dimension_descriptions.json"

    direct = library_path / filename
    if direct.exists():
        return direct

    return None


def _ensure_assembly_files():
    """Copy assembly profile and view images into 400S_Sorted_Library/assemblies/ if not already there."""
    assemblies_dir = library_path("assemblies")
    assemblies_dir.mkdir(parents=True, exist_ok=True)

    # Copy assembly JSON files from project root into assemblies/ dir
    for src in Path(".").glob("*_assembly.json"):
        dest = assemblies_dir / src.name
        if not dest.exists():
            shutil.copy2(str(src), str(dest))
            logger.info(f"Copied {src.name} -> {dest}")

    # Copy assembly view PNGs (e.g. 6000056_view_front.png) from project root
    for src in Path(".").glob("*_view_*.png"):
        # Only copy if the corresponding assembly JSON exists in assemblies/
        # Extract potential assembly number: 6000056_view_front.png -> 6000056
        stem_parts = src.stem.split("_view_")
        if len(stem_parts) == 2:
            assy_num = stem_parts[0]
            assy_json = assemblies_dir / f"{assy_num}_assembly.json"
            if assy_json.exists():
                dest = assemblies_dir / src.name
                if not dest.exists():
                    shutil.copy2(str(src), str(dest))
                    logger.info(f"Copied {src.name} -> {dest}")

    # Copy colored GLB files (e.g. 6000056_colored.glb) from project root
    for src in Path(".").glob("*_colored.glb"):
        dest = assemblies_dir / src.name
        if not dest.exists():
            shutil.copy2(str(src), str(dest))
            logger.info(f"Copied {src.name} -> {dest}")


def _index_assembly_profile(assy_number: str, assy_data: dict) -> int:
    assembly_profiles[assy_number] = assy_data
    mappings = 0
    components = assy_data.get("components", [])
    seen_parts = set()
    for comp in components:
        if comp.get("type") != "Part":
            continue
        ref_file = comp.get("referencedFileName", "")
        if ref_file:
            part_num = re.sub(r"_\d+$", "", Path(ref_file).stem)
        else:
            part_num = re.sub(r"-\d+$", "", comp.get("name", ""))
        if part_num and part_num not in seen_parts:
            seen_parts.add(part_num)
            assemblies = assembly_part_lookup.setdefault(part_num, [])
            if assy_number not in assemblies:
                assemblies.append(assy_number)
                mappings += 1

    part_data_cache = assy_data.get("partDataCache", {})
    for part_data in part_data_cache.values():
        ident = part_data.get("identity") or {}
        new_pn = (
            (ident.get("customProperties") or {}).get("PartNo", "")
        ).strip()
        if not new_pn:
            new_pn = (ident.get("partNumber") or "").strip()
        if new_pn and new_pn not in seen_parts:
            seen_parts.add(new_pn)
            assemblies = assembly_part_lookup.setdefault(new_pn, [])
            if assy_number not in assemblies:
                assemblies.append(assy_number)
                mappings += 1
    return mappings


def _load_assembly_profiles():
    """Load legacy and prepared-package assemblies into one viewer registry."""
    global assembly_part_lookup, assembly_profiles, prepared_assembly_sources

    assembly_part_lookup = {}
    assembly_profiles = {}
    prepared_assembly_sources = {}

    registry_path = library_path(PART_NUMBER_REGISTRY_FILENAME)
    try:
        part_number_registry = load_part_number_registry(registry_path)
    except PartNumberRegistryError as exc:
        logger.error("Ignoring invalid part-number registry %s: %s", registry_path, exc)
        part_number_registry = {"schemaVersion": 1, "assignments": []}

    assemblies_dir = library_path("assemblies")
    assembly_files = (
        sorted(assemblies_dir.glob("*_assembly.json"))
        if assemblies_dir.exists()
        else []
    )
    if not assembly_files:
        logger.info("No legacy assembly profiles found in assemblies/.")

    total_mappings = 0
    for assy_file in assembly_files:
        assy_number = assy_file.stem.replace("_assembly", "")
        try:
            with open(assy_file, "r", encoding="utf-8-sig") as f:
                assy_data = json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            logger.warning(f"Failed to load assembly profile {assy_file.name}: {e}")
            continue
        assignment_report = apply_part_number_registry(
            assy_data,
            part_number_registry,
            product_id=assy_number,
        )
        if assignment_report["assignmentCount"]:
            logger.info(
                "Applied %s library part-number assignment(s) to assembly %s",
                len(assignment_report["appliedPartNumbers"]),
                assy_number,
            )
        total_mappings += _index_assembly_profile(assy_number, assy_data)

    prepared_assembly_sources = _discover_prepared_assembly_sources()
    try:
        documentation_library_sources = load_documentation_library_sources(
            REPO_ROOT
        )
    except DocumentationLibraryRegistryError as exc:
        logger.error("Unable to load Documentation assembly registry: %s", exc)
        documentation_library_sources = {}
    for assy_number, source in documentation_library_sources.items():
        if assy_number in prepared_assembly_sources:
            logger.error(
                "Documentation library assembly %s collides with a prepared package and was skipped.",
                assy_number,
            )
            continue
        prepared_assembly_sources[assy_number] = source
    for assy_number, source in prepared_assembly_sources.items():
        if assy_number in assembly_profiles:
            logger.warning(
                "Prepared assembly %s is shadowed by a legacy library profile.",
                assy_number,
            )
            continue
        assignment_report = apply_part_number_registry(
            source["profile"],
            part_number_registry,
            product_id=assy_number,
        )
        source["partNumberAssignmentReport"] = assignment_report
        if assignment_report["assignmentCount"]:
            logger.info(
                "Applied %s library part-number assignment(s) to prepared assembly %s",
                len(assignment_report["appliedPartNumbers"]),
                assy_number,
            )
        total_mappings += _index_assembly_profile(
            assy_number,
            source["profile"],
        )

    logger.info(
        "Loaded %s assembly profile(s), including %s prepared source(s), "
        "with %s part-to-assembly mappings",
        len(assembly_profiles),
        len(prepared_assembly_sources),
        total_mappings,
    )


def _component_matches_aliases(component_name: str, aliases: set) -> bool:
    """Check if a componentName matches any alias using exact prefix matching.

    ComponentName format is '{part_number}-{instance}' or '{part}_{config}-{instance}'.
    Substring matching would false-positive: alias '101' would match '1015001-1'.
    Instead, strip the trailing instance suffix and check for exact match.
    """
    # Strip instance suffix: '1015003-1' -> '1015003', '022-807_2-1' -> '022-807_2'
    base = re.sub(r'-\d+$', '', component_name)
    if base in aliases:
        return True
    # Also strip config suffix: '022-807_2' -> '022-807'
    base_no_config = re.sub(r'_\d+$', '', base)
    return base_no_config in aliases


MAX_MATE_LINES = 20  # Cap mate lines to prevent context size explosion


def _compute_nearby_parts(available_parts: list, selected_pns: set, max_neighbors: int = 5) -> dict:
    """Compute nearest parts using minimum distance across all instances."""
    # Build instance map: pn -> list of [x,y,z]
    instance_map = {}
    desc_map = {}
    for ap in available_parts:
        pn = ap.get("part_number", "")
        c = ap.get("centroid_mm")
        if pn and c:
            instance_map[pn] = c  # already a list of [x,y,z] arrays
            desc_map[pn] = ap.get("description", "")

    result = {}
    for sel_pn in selected_pns:
        if sel_pn not in instance_map:
            continue
        sel_positions = instance_map[sel_pn]
        distances = []
        for pn, positions in instance_map.items():
            if pn == sel_pn:
                continue
            # Min distance across all instance pairs (closest instance wins)
            min_d = float('inf')
            for sp in sel_positions:
                for tp in positions:
                    d = math.sqrt((sp[0]-tp[0])**2 + (sp[1]-tp[1])**2 + (sp[2]-tp[2])**2)
                    if d < min_d:
                        min_d = d
            distances.append({
                "part_number": pn,
                "description": desc_map.get(pn, ""),
                "distance_mm": round(min_d, 1),
                "instances": len(positions)
            })
        distances.sort(key=lambda x: x["distance_mm"])
        result[sel_pn] = distances[:max_neighbors]
    return result


@asynccontextmanager
async def lifespan(app: FastAPI):
    """Initialize SpatialInspector and optional Playwright browser on startup."""
    global inspector, search_engine
    logger.info("Initializing SpatialInspector with library_dir=%r...", str(LIBRARY_DIR))
    try:
        inspector = SpatialInspector(library_dir=str(LIBRARY_DIR))
        logger.info("SpatialInspector initialized successfully.")
    except Exception as e:
        inspector = None
        logger.warning("SpatialInspector unavailable at startup; app will serve available static/demo routes only: %s", e)

    # Copy assembly files into library and build reverse-lookup maps
    try:
        _ensure_assembly_files()
        _load_assembly_profiles()
        logger.info(f"Assembly lookup contains {len(assembly_part_lookup)} part numbers across {len(assembly_profiles)} assemblies")
    except Exception as e:
        logger.error(f"Failed to load assembly profiles: {e}", exc_info=True)

    # Start Playwright browser engine for Scout web search (optional)
    try:
        from ai_inspector.search.browser_engine import BrowserSearchEngine
        search_engine = BrowserSearchEngine()
        await search_engine.start()
        logger.info("Scout browser search engine started")
    except Exception as e:
        logger.warning(f"Scout browser search engine unavailable: {e}")
        search_engine = None

    yield

    # Shutdown
    if search_engine:
        await search_engine.stop()
    logger.info("Shutting down InspectorPro server.")


app = FastAPI(
    title="InspectorPro",
    description="Engineering drawing quality inspection API",
    version="1.0.0",
    lifespan=lifespan,
)

def _configured_cors_origins() -> list[str]:
    return [
        origin.strip().rstrip("/")
        for origin in os.getenv("INSPECTORPRO_ALLOWED_ORIGINS", "").split(",")
        if origin.strip()
    ]


def _configured_allowed_hosts() -> set[str]:
    return {
        host.strip().lower().rstrip(".")
        for host in os.getenv("INSPECTORPRO_ALLOWED_HOSTS", "").split(",")
        if host.strip()
    }


def _normalized_http_origin(value: str) -> tuple[str, str] | None:
    candidate = str(value or "").strip().rstrip("/")
    if not candidate:
        return None
    try:
        parsed = urlsplit(candidate)
        port = parsed.port
    except ValueError:
        return None
    if (
        parsed.scheme.lower() not in {"http", "https"}
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
        or parsed.path
        or parsed.query
        or parsed.fragment
    ):
        return None
    hostname = parsed.hostname.lower().rstrip(".")
    authority = hostname
    if ":" in hostname:
        authority = f"[{hostname}]"
    if port is not None:
        authority = f"{authority}:{port}"
    return f"{parsed.scheme.lower()}://{authority}", authority


def _normalized_request_authority(value: str) -> str | None:
    candidate = str(value or "").strip()
    if not candidate or any(char in candidate for char in "/?#@"):
        return None
    try:
        parsed = urlsplit(f"//{candidate}")
        port = parsed.port
    except ValueError:
        return None
    if not parsed.hostname or parsed.username is not None:
        return None
    hostname = parsed.hostname.lower().rstrip(".")
    authority = hostname
    if ":" in hostname:
        authority = f"[{hostname}]"
    if port is not None:
        authority = f"{authority}:{port}"
    return authority


def _authority_hostname(authority: str) -> str | None:
    try:
        return urlsplit(f"//{authority}").hostname
    except ValueError:
        return None


def _is_loopback_authority(authority: str) -> bool:
    hostname = _authority_hostname(authority)
    if not hostname:
        return False
    if hostname.lower().rstrip(".") == "localhost":
        return True
    try:
        return ipaddress.ip_address(hostname).is_loopback
    except ValueError:
        return False


def _authority_is_explicitly_allowed(authority: str) -> bool:
    allowed = _configured_allowed_hosts()
    return (
        authority.lower().rstrip(".") in allowed
        or str(_authority_hostname(authority) or "").lower().rstrip(".")
        in allowed
    )


# Same-origin product traffic does not need CORS. Explicit deployments may add
# trusted origins, while loopback ports remain available for local development.
app.add_middleware(
    CORSMiddleware,
    allow_origins=_configured_cors_origins(),
    allow_origin_regex=(
        r"^https?://(?:127(?:\.\d{1,3}){3}|localhost|\[::1\])"
        r"(?::\d+)?$"
    ),
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


def _request_origin_is_trusted(request: Request) -> bool:
    raw_origin = str(request.headers.get("origin") or "").strip()
    if not raw_origin:
        return True

    normalized = _normalized_http_origin(raw_origin)
    if normalized is None:
        return False
    origin, origin_authority = normalized
    configured_origins = {
        normalized_origin[0].casefold()
        for value in _configured_cors_origins()
        if (normalized_origin := _normalized_http_origin(value)) is not None
    }
    if origin.casefold() in configured_origins:
        return True
    if (
        _is_loopback_authority(origin_authority)
        or _authority_is_explicitly_allowed(origin_authority)
    ):
        return True

    request_authority = _normalized_request_authority(
        request.headers.get("host", "")
    )
    if (
        request_authority is None
        or not _authority_is_explicitly_allowed(request_authority)
    ):
        return False
    request_origin = f"{request.url.scheme.lower()}://{request_authority}"
    return origin.casefold() == request_origin.casefold()


def _is_facility_authority_path(path: str) -> bool:
    return (
        path.startswith("/api/facility-")
        or path.startswith("/api/industrial-assets")
        or path.startswith("/api/training/facility-layout")
    )


@app.middleware("http")
async def _facility_layout_same_origin_boundary(request: Request, call_next):
    if (
        _is_facility_authority_path(request.url.path)
        and not _request_origin_is_trusted(request)
    ):
        return JSONResponse(
            status_code=403,
            content={
                "error": {
                    "code": "facility_origin_forbidden",
                    "message": (
                        "Facility Layout requests must originate from the "
                        "InspectorPro application or an explicitly trusted "
                        "origin."
                    ),
                }
            },
        )
    return await call_next(request)

