SAGE_ANTHROPIC_MODEL_DEFAULT = "claude-sonnet-4-5-20250929"
SAGE_OPENAI_MODEL_DEFAULT = "gpt-5.6-sol"
_OPENAI_REASONING_EFFORTS = {"none", "low", "medium", "high", "xhigh", "max"}


@dataclass(frozen=True)
class SageAnswerProviderConfig:
    """Sage answer/planning provider, optionally bound to the Facility gateway.

    Facility routing and research have separate explicit gateway roles.
    Authorization and deterministic geometry never belong to the provider.
    """

    provider: str
    model: str
    api_key: str
    reasoning_effort: Optional[str] = None
    gateway_route: Optional[GatewayRoute] = None


def _facility_skill_compatible_models() -> Tuple[str, ...]:
    """Return the live Facility skill compatibility intersection."""

    try:
        _workflows, skills = _get_agent_skill_runtime()
        packages = (
            skills.get("generate-facility-layout"),
            skills.get("analyze-facility-layout"),
        )
        compatible = set(packages[0].contract.compatible_models)
        for package in packages[1:]:
            compatible.intersection_update(package.contract.compatible_models)
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "error": {
                    "code": "facility_model_mismatch",
                    "message": (
                        "Facility skill compatibility could not be verified "
                        "before provider execution."
                    ),
                }
            },
        ) from exc
    if not compatible:
        raise HTTPException(
            status_code=500,
            detail={
                "error": {
                    "code": "facility_model_mismatch",
                    "message": "Facility skills have no common compatible model.",
                }
            },
        )
    return tuple(sorted(compatible))


def _sage_answer_provider_config(
    agent_type: str,
    *,
    active_mode: str = "",
) -> SageAnswerProviderConfig:
    """Return the opt-in final-answer provider configuration for Sage."""

    if str(active_mode or "").strip().lower() == "facility_layout":
        try:
            facility_config = resolve_facility_provider_config(
                os.environ,
                compatible_models=_facility_skill_compatible_models(),
                enforce_frozen=True,
            )
        except FacilityProviderConfigurationError as exc:
            raise HTTPException(
                status_code=500,
                detail={
                    "error": {
                        "code": exc.code,
                        "message": str(exc),
                        "details": dict(exc.details),
                    }
                },
            ) from exc
        key_name = (
            "OPENAI_API_KEY"
            if facility_config.provider == "openai"
            else "ANTHROPIC_API_KEY"
        )
        api_key = os.getenv(key_name, "").strip()
        if not api_key:
            raise HTTPException(
                status_code=500,
                detail=f"{key_name} not configured. Set it in your .env file.",
            )
        return SageAnswerProviderConfig(
            provider=facility_config.provider,
            model=facility_config.model,
            api_key=api_key,
            reasoning_effort=facility_config.reasoning_effort,
            gateway_route=facility_config.gateway_route,
        )

    if str(agent_type or "").strip().lower() != "deviation-analyst":
        provider = "anthropic"
    else:
        provider = str(
            os.getenv("INSPECTORPRO_SAGE_PROVIDER", "anthropic")
        ).strip().lower()
    if provider not in {"anthropic", "openai"}:
        raise HTTPException(
            status_code=500,
            detail=(
                "INSPECTORPRO_SAGE_PROVIDER must be 'anthropic' or 'openai'."
            ),
        )

    if provider == "openai":
        api_key = os.getenv("OPENAI_API_KEY", "").strip()
        if not api_key:
            raise HTTPException(
                status_code=500,
                detail="OPENAI_API_KEY not configured. Set it in your .env file.",
            )
        model = str(
            os.getenv("INSPECTORPRO_SAGE_OPENAI_MODEL", SAGE_OPENAI_MODEL_DEFAULT)
        ).strip() or SAGE_OPENAI_MODEL_DEFAULT
        effort = str(
            os.getenv("INSPECTORPRO_SAGE_OPENAI_REASONING_EFFORT", "medium")
        ).strip().lower()
        if effort not in _OPENAI_REASONING_EFFORTS:
            raise HTTPException(
                status_code=500,
                detail=(
                    "INSPECTORPRO_SAGE_OPENAI_REASONING_EFFORT must be one of "
                    f"{', '.join(sorted(_OPENAI_REASONING_EFFORTS))}."
                ),
            )
        return SageAnswerProviderConfig(
            provider="openai",
            model=model,
            api_key=api_key,
            reasoning_effort=effort,
        )

    api_key = os.getenv("ANTHROPIC_API_KEY", "").strip()
    if not api_key:
        raise HTTPException(
            status_code=500,
            detail="ANTHROPIC_API_KEY not configured. Set it in your .env file.",
        )
    model = str(
        os.getenv("INSPECTORPRO_SAGE_ANTHROPIC_MODEL", SAGE_ANTHROPIC_MODEL_DEFAULT)
    ).strip() or SAGE_ANTHROPIC_MODEL_DEFAULT
    return SageAnswerProviderConfig(
        provider="anthropic",
        model=model,
        api_key=api_key,
    )


def _record_sage_answer_call(
    provider: str,
    *,
    model: str,
    response: Optional[Any],
    latency_ms: float,
    status: str = "success",
    errorType: Optional[str] = None,
    **tags: Any,
) -> None:
    """Send final-answer telemetry to the matching provider adapter."""

    recorder = record_openai_call if provider == "openai" else record_anthropic_call
    recorder(
        model=model,
        response=response,
        latency_ms=latency_ms,
        status=status,
        errorType=errorType,
        **tags,
    )


